function check(input, actual, expected) {
  const [nums1, nums2, k] = input;
  if (!Array.isArray(actual) || !Array.isArray(expected) || actual.length !== k) return false;
  const tally = list => {
    const counts = new Map();
    for (const value of list) counts.set(value, (counts.get(value) || 0) + 1);
    return counts;
  };
  const in1 = tally(nums1), in2 = tally(nums2), used = new Map();
  for (const pair of actual) {
    if (!Array.isArray(pair) || pair.length !== 2) return false;
    const [u, v] = pair;
    if (!in1.has(u) || !in2.has(v)) return false;
    // A value pair can appear at most as many times as there are position pairs that form it.
    const key = u + ',' + v;
    used.set(key, (used.get(key) || 0) + 1);
    if (used.get(key) > in1.get(u) * in2.get(v)) return false;
  }
  const sums = list => list.map(([u, v]) => u + v).sort((a, b) => a - b);
  const got = sums(actual), want = sums(expected);
  return got.every((sum, i) => sum === want[i]);
}

