function validate([nums1, nums2, k]) {
  if (nums1.length < 1 || nums1.length > 100000) return 'nums1 needs 1 to 10^5 values.';
  if (nums2.length < 1 || nums2.length > 100000) return 'nums2 needs 1 to 10^5 values.';
  for (const nums of [nums1, nums2]) {
    if (nums.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Each value is a whole number from -10^9 to 10^9.';
    for (let i = 1; i < nums.length; i++) if (nums[i] < nums[i - 1]) return 'nums1 and nums2 must be sorted in non-decreasing order.';
  }
  if (!Number.isInteger(k) || k < 1 || k > 10000) return 'k is a whole number from 1 to 10^4.';
  if (k > nums1.length * nums2.length) return 'k cannot exceed the number of possible pairs.';
  return null;
}

