function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const sorted = (n, low, high) => Array.from({ length: n }, () => pick(low, high)).sort((a, b) => a - b);
  if (size === 'large') {
    const nums1 = sorted(2000, -1000000000, 1000000000);
    const nums2 = sorted(2000, -1000000000, 1000000000);
    return [nums1, nums2, 10000];
  }
  const span = rand() < 0.5 ? 4 : 1000000000;
  const nums1 = sorted(pick(1, 6), -span, span);
  const nums2 = sorted(pick(1, 6), -span, span);
  return [nums1, nums2, pick(1, nums1.length * nums2.length)];
}
